        .hero-card { padding: 3rem; }
        .role-panel { padding: 1rem; }
        .fixify-card, .stat-card, .empty-state { padding: 1.5rem; }

        .role-card {
            background: linear-gradient(135deg, rgba(13, 110, 253, 0.28), rgba(255,255,255,0.05));
            border: 1px solid rgba(255,255,255,0.14);
            border-radius: 18px;
            color: var(--fixify-white);
            padding: 1.25rem;
            transition: transform 0.2s ease, border-color 0.2s ease;
        }

        .role-card:hover {
            border-color: rgba(13, 110, 253, 0.95);
            transform: translateY(-3px);
        }

        .role-card h3 { font-weight: 800; }
        .role-card p { color: var(--fixify-muted); margin-bottom: 0; }
        .role-arrow { color: var(--fixify-blue); font-size: 2rem; }

        .eyebrow {
            color: #7db7ff;
            font-size: 0.8rem;
            font-weight: 800;
            letter-spacing: 0.16em;
            text-transform: uppercase;
        }

        .btn-fixify {
            background: var(--fixify-blue);
            border: 1px solid var(--fixify-blue);
            color: var(--fixify-white);
            font-weight: 700;
            border-radius: 999px;
            padding: 0.75rem 1.35rem;
        }

        .btn-fixify:hover {
            background: #075bd8;
            color: var(--fixify-white);
        }

        .dashboard-header {
            display: flex;
            align-items: center;
