        }

        .stat-card span {
            color: var(--fixify-muted);
            display: block;
            font-size: 0.9rem;
        }

        .stat-card strong {
            color: var(--fixify-white);
            display: block;
            font-size: 2rem;
            margin-top: 0.3rem;
        }

        .job-meta {
            display: flex;
            flex-wrap: wrap;
            gap: 0.5rem;
        }

        .job-meta span {
            background: rgba(13, 110, 253, 0.18);
            border: 1px solid rgba(13, 110, 253, 0.32);
            border-radius: 999px;
            color: #dbeafe;
            font-size: 0.85rem;
