        }

        .bid-count {
            align-items: center;
            background: var(--fixify-blue);
            border-radius: 999px;
            color: var(--fixify-white);
            display: inline-flex;
            font-weight: 800;
            height: 2.4rem;
            justify-content: center;
            min-width: 2.4rem;
        }

        .empty-state {
            color: var(--fixify-white);
            text-align: center;
        }

        .empty-state p { color: var(--fixify-muted); }

        /* Added: shared job photo styling. */
        .job-photo {
            border: 1px solid rgba(255,255,255,0.14);
            border-radius: 18px;
            height: 210px;
            object-fit: cover;
            width: 100%;
        }

        .portfolio-grid {
            display: grid;
            gap: 1rem;
            grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
        }

        .portfolio-item {
            align-items: center;
            background: rgba(13, 110, 253, 0.14);
            border: 1px dashed rgba(125, 183, 255, 0.55);
            border-radius: 16px;
            color: var(--fixify-white);
